  it('소문자/공백 허용', () => {
    expect(mbtiSignals(' entj ')).toEqual({ A1:1, A2:1, A3:1, A4:1, A5:0 });
  });
  it('weak=true 면 ±0.5 (간이 12문항 약신호)', () => {
